const trigger = $('When Executed by Another Workflow').item.json;
const r = $json ?? {};
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};

if (code >= 300 || (body && body.errors)) {
  throw new Error('Directus /items/services devolvió ' + code + ': ' + JSON.stringify(body.errors || body));
}

const services = Array.isArray(body.data) ? body.data : [];

const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const clean = v => (v === undefined || v === null) ? null : (String(v).trim() || null);
const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

const single = (id, name) => [{ json: { status: 'single', service_id: id, service_name: name } }];
const multiple = (list) => [{ json: { status: 'multiple', candidates: list.map(s => ({ id: s.id, name: s.name })) } }];
const notFound = (q) => [{ json: { status: 'not_found', service_query: q ?? null } }];

// 1) passthrough: service_id ya resuelto
const passId = clean(trigger.service_id);
if (passId && uuid.test(passId)) {
  const m = services.find(s => s.id === passId);
  return single(passId, m ? m.name : null);
}

if (!services.length) return notFound(clean(trigger.service_query));

// Palabras que no distinguen un servicio de otro. Se quitan en TODAS las comparaciones,
// no solo en una: con "la demo" el solape de palabras contaba el "la" y empataba la demo
// con "Declaración de la renta" -- el cliente oía "¿la renta o la demo?" (2/oct/2026).
const VACIAS = new Set(['de','del','la','las','el','los','y','e','o','u','a','al','en',
  'con','para','por','un','una','unos','unas','mi','tu','su','que','lo']);
const propias = s => s.split(' ').filter(t => t.length > 1 && !VACIAS.has(t));

const opts = services.map(s => ({ id: s.id, name: s.name, n: norm(s.name), p: propias(norm(s.name)).join(' ') }));
const q = norm(trigger.service_query);
const qp = propias(q).join(' ');

// 2) sin query: si solo hay 1 servicio activo, es ese.
if (!qp && opts.length === 1) return single(opts[0].id, opts[0].name);

// 2b) Sin query pero con el mensaje del cliente: el agente a veces no rellena `servicio`
// aunque el cliente lo haya nombrado ("apúntame a la demo, soy Ana, de Acme..."), y el
// cliente acababa eligiendo de una lista lo que ya había dicho (2/oct/2026, 2 de cada 3
// veces con gpt-4o pese a decírselo en el prompt). El texto lo pasa el Core tal cual, sin
// el modelo de por medio. Solo cuentan las palabras PROPIAS del nombre del servicio -- sin
// "de", "la", "y"... --, porque con ellas "Declaración de la renta" empataba con "Demo de
// Aegora" en cualquier frase con un "de". Y solo vale un ganador claro; si no, como antes.
if (!qp) {
  const texto = new Set(propias(norm(trigger.texto_cliente)));
  if (texto.size) {
    const puntos = opts.map(s => ({ s, p: propias(s.n).filter(t => texto.has(t)).length }))
      .filter(x => x.p > 0).sort((x, y) => y.p - x.p);
    if (puntos.length === 1 || (puntos.length > 1 && puntos[0].p > puntos[1].p)) {
      return single(puntos[0].s.id, puntos[0].s.name);
    }
  }
  return multiple(opts);
}

// 3) match exacto (con y sin palabras vacías: "la demo de aegora" es la demo)
let hit = opts.filter(s => s.n === q || (qp && s.p === qp));
if (hit.length === 1) return single(hit[0].id, hit[0].name);

// 4) substring en cualquier dirección, sobre las palabras propias
if (qp) {
  hit = opts.filter(s => s.p && (s.p.includes(qp) || qp.includes(s.p)));
  if (hit.length === 1) return single(hit[0].id, hit[0].name);
  if (hit.length > 1) return multiple(hit);
}

// 5) solape de palabras propias
const qt = new Set(qp.split(' ').filter(Boolean));
const scored = opts
  .map(s => ({ s, score: s.p.split(' ').filter(t => qt.has(t)).length }))
  .filter(x => x.score > 0)
  .sort((a, b) => b.score - a.score);

if (scored.length === 1) return single(scored[0].s.id, scored[0].s.name);
if (scored.length > 1 && scored[0].score > scored[1].score) return single(scored[0].s.id, scored[0].s.name);
if (scored.length > 1) return multiple(scored.map(x => x.s));

return notFound(clean(trigger.service_query));
